 useEffect(()=>{const ids=profile.role==="admin"?(location==="ALL"?locations.map(x=>x.id):[location]):[profile.locationId];const us=ids.map(id=>onSnapshot(query(collection(db,"visitors"),where("locationId","==",id)),s=>setRows(old=>[...old.filter(x=>x.locationId!==id),...s.docs.map(d=>({id:d.id,...d.data()}))])));return()=>us.forEach(x=>x())},[profile,location,refresh]);
