function VisitorRow({r}:{r:any}){const checkout=async()=>{try{const batch=writeBatch(db);const now=serverTimestamp();batch.update(doc(db,"visitors",r.id),{checkOutAt:now,updatedAt:now});if(r.appointmentId){batch.update(doc(db,"visitorAppointments",r.appointmentId),{status:"CHECKED_OUT",checkedOutAt:now,checkedOutBy:r.securityId||"",checkedOutByName:r.securityName||"",updatedAt:now})}await batch.commit()}catch(e:any){alert(e.message||"Could not check out visitor.")}};return <tr><td><b>{r.serialNo}</b><small>{r.entryDate||r.date}</small></td><td><b>{r.name}</b><small>{r.mobile}</small>{r.photoUrl&&<button type="button" className="photoThumbBtn" onClick={()=>window.dispatchEvent(new CustomEvent("vms-photo",{detail:r.photoUrl}))}><img className="visitorThumb" src={r.photoUrl} alt="Visitor" loading="lazy" decoding="async"/></button>}</td><td>{r.company||"—"}</td><td>{r.whomToMeet||"—"}<small>{r.purpose}</small></td><td>{fmt(r.checkInAt)}</td><td>{fmt(r.checkOutAt)}</td><td>{r.checkOutAt?<span className="badge neutral">Checked out</span>:<span className="badge green">Inside</span>}</td><td>{locName(r.locationId)}</td><td>{!r.checkOutAt&&<button className="checkout" onClick={checkout}><CheckCircle2 size={15}/> Check out</button>}</td></tr>}
