 const shown=rows.filter(r=>[r.passNo,r.activity,r.workArea,r.contractorName,r.idNumber,r.supervisorName,r.mobile,...(r.personNames||[])].join(" ").toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>String(b.createdAt?.toMillis?.()||0).localeCompare(String(a.createdAt?.toMillis?.()||0)));
