  const baseSettings=await loadPrintSettings("nonRoutine");const settings=mode==="thermal"?{...baseSettings,format:baseSettings.thermalWidth===58?"THERMAL_58":"THERMAL_80"}:mode==="label"?{...baseSettings,format:(baseSettings.format==="LABEL_4X6"||baseSettings.format==="LABEL_4X12")?baseSettings.format:"LABEL_4X6"}:baseSettings;
