 return <Modal title="Internal transfer pass" onClose={onClose}><div className="transferPreview"><div className="previewToolbar"><div><span>TRANSFER DOCUMENT</span><b>Internal Asset Movement</b></div><div className="previewMeta">A4 · Security document</div></div><div className="transferPassCard" style={previewPrintStyle(printSettings)}><div className="transferPassBrand"><div><small>SAIDHARA NDC · INTERNAL MOVEMENT</small><h1>TRANSFER PASS</h1><p>Authorized movement between NDC locations</p></div><span className="transferPassStatus">{transfer.status==="RECEIVED_CLOSED"?"RECEIVED & CLOSED":"SENT"}</span></div><div className="transferPassBody"><div className="transferIdentity"><div className="transferIdentityCode"><span>TRANSFER REFERENCE</span><b>{transfer.transferNo}</b><small>Internal movement control ID</small></div><div className="transferIdentityMeta"><span className="transferPill">INTERNAL ASSET TRANSFER</span><div><small>STATUS</small><b>{transfer.status==="RECEIVED_CLOSED"?"CLOSED":"IN TRANSIT"}</b></div></div></div><div className="transferGrid"><div className="transferInfo"><label>ITEM NAME</label><strong>{transfer.itemName}</strong></div><div className="transferInfo"><label>QUANTITY</label><strong>{transfer.quantity}</strong></div><div className="transferInfo"><label>ASSET / SERIAL NUMBER</label><strong>{transfer.assetNumber||"—"}</strong></div><div className="transferInfo"><label>DESCRIPTION</label><strong>{transfer.description||"—"}</strong></div><div className="transferInfo"><label>ISSUED BY PERSON</label><strong>{transfer.issuedByPerson}</strong></div><div className="transferInfo"><label>SENDING VIA PERSON</label><strong>{transfer.sendingViaPerson}</strong></div></div><div className="transferRoute"><div className="transferInfo"><label>SENT FROM</label><strong>{locName(transfer.sourceLocationId,locations)}</strong></div><div className="transferInfo"><label>SENT TO</label><strong>{locName(transfer.destinationLocationId,locations)}</strong></div></div><div className="transferBarcode"><svg ref={refSvg}/><small>Scan barcode to retrieve this internal transfer · Code {transfer.barcodeValue}</small></div><div className="transferFoot"><span>Issued: {fmt(transfer.createdAt)}</span><span>{transfer.status==="RECEIVED_CLOSED"?"Received: "+fmt(transfer.receivedAt):"Awaiting receipt at destination"}</span></div><div className="transferNote">Destination security must verify the material and close this transfer after physical receipt.</div></div></div><div className="previewHint"><ShieldCheck size={14}/> Transfer receipt is recorded separately from ordinary gate-pass returns.</div></div><div className="modalActions"><button className="secondary" onClick={onClose}>Close</button><button className="secondary" onClick={()=>print("thermal")}><Printer size={16}/> Thermal</button><button className="secondary" onClick={()=>print("label")}><Printer size={16}/> Print on Label</button><button className="primary" onClick={()=>print("paper")}><Printer size={16}/> {printing?"Opening print…":"Print transfer pass"}</button></div></Modal>;
